import * as React from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '../badge/Badge';
import { Card, CardContent } from '../card/Card';

export type TombstoneStatus = 'archived' | 'unavailable' | 'closed';

export type TombstoneCardProps = Omit<React.HTMLAttributes<HTMLElement>, 'title'> & {
  /** Listing, deal or document name. */
  title: string;
  /** Why the item is unavailable. */
  reason?: string;
  /** Unavailable state. Default 'unavailable'. */
  status?: TombstoneStatus;
  /** Logo or document icon slot. */
  logo?: React.ReactNode;
  /** Optional detail destination. */
  href?: string;
  /** Link label. Default "View details". */
  actionLabel?: string;
  /** Custom link element for routers. */
  linkComponent?: React.ElementType;
};

const statusConfig: Record<TombstoneStatus, { label: string; variant: 'secondary' | 'warning' | 'outline' }> = {
  archived: { label: 'Archived', variant: 'secondary' },
  unavailable: { label: 'Unavailable', variant: 'warning' },
  closed: { label: 'Closed', variant: 'outline' },
};

/**
 * Placeholder card for archived, closed or unavailable marketplace items. It
 * explains why the item is unavailable instead of silently removing it from a
 * list or leaving a broken detail link.
 */
export const TombstoneCard = React.forwardRef<HTMLElement, TombstoneCardProps>(function TombstoneCard(
  {
    title,
    reason,
    status = 'unavailable',
    logo,
    href,
    actionLabel = 'View details',
    linkComponent,
    className,
    ...props
  },
  ref
) {
  const Link = linkComponent ?? 'a';
  const statusInfo = statusConfig[status];

  return (
    <Card
      ref={ref as never}
      className={cn('flex h-full flex-col border-dashed bg-muted/30 shadow-none', className)}
      {...props}
    >
      <CardContent className="flex flex-1 flex-col gap-3 p-5">
        <div className="flex items-start justify-between gap-2">
          {logo && <div className="min-w-0 opacity-70">{logo}</div>}
          <Badge variant={statusInfo.variant}>{statusInfo.label}</Badge>
        </div>
        <h3 className="text-base font-semibold tracking-tight text-foreground/80">{title}</h3>
        {reason && <p className="text-sm leading-relaxed text-muted-foreground">{reason}</p>}
        {href && (
          <Link
            href={href}
            className="mt-auto text-sm font-medium text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {actionLabel}
          </Link>
        )}
      </CardContent>
    </Card>
  );
});

{
  "id": "tombstone-card",
  "name": "TombstoneCard",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.5.0",
  "sourceDir": "tombstone-card",
  "exportName": "TombstoneCard",
  "description": "Placeholder card for archived, closed or unavailable marketplace items.",
  "designIntent": "Removing unavailable items silently breaks saved links and user expectations. TombstoneCard keeps the item in place and states the reason and status.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Listing, deal or document name."
    },
    {
      "name": "reason",
      "type": "string",
      "required": false,
      "description": "Why the item is unavailable."
    },
    {
      "name": "status",
      "type": "'archived' | 'unavailable' | 'closed'",
      "required": false,
      "defaultValue": "unavailable",
      "enum": [
        "archived",
        "unavailable",
        "closed"
      ],
      "description": "Unavailable state."
    },
    {
      "name": "logo",
      "type": "ReactNode",
      "required": false,
      "description": "Logo or document icon slot."
    },
    {
      "name": "href",
      "type": "string",
      "required": false,
      "description": "Optional detail destination."
    },
    {
      "name": "actionLabel",
      "type": "string",
      "required": false,
      "defaultValue": "View details",
      "description": "Link label."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Custom link element for routers."
    }
  ],
  "examples": [
    {
      "title": "Archived listing",
      "code": "<TombstoneCard\n  title=\"Archived listing\"\n  reason=\"This listing closed in 2025.\"\n  status=\"archived\"\n  href=\"/deals/archived\"\n/>",
      "description": "A muted card that explains why the listing is unavailable."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't remove the item without explanation",
      "explanation": "A saved link or bookmark should still resolve to a card that explains the state.",
      "example": "<TombstoneCard title=\".\" reason=\".\" />"
    }
  ],
  "accessibility": [
    {
      "feature": "Status text",
      "implementation": "The unavailable state is a text badge, not color alone",
      "userRequirements": "Keep the reason specific"
    }
  ],
  "compositionRules": [
    {
      "component": "Grid",
      "relationship": "Use in place of a DealCard or EntityCard when the item is unavailable",
      "example": "<Grid><TombstoneCard ... /></Grid>"
    }
  ],
  "relatedComponents": [
    "Card",
    "Badge",
    "DealCard",
    "EntityCard"
  ]
}
